import { cc, type SinwanNode } from "sinwan/component";
import { ArrowDown, ArrowUp, ChevronsUpDown, EyeOff } from "lucide";
import type { RowData } from "@tanstack/table-core";

import { Icon } from "@/lib/icons";
import { cn } from "@/lib/utils";
import { buttonVariants } from "@/components/ui/button";
import {
  DropdownMenu,
  DropdownMenuContent,
  DropdownMenuItem,
  DropdownMenuSeparator,
  DropdownMenuTrigger,
} from "@/components/ui/dropdown-menu";
import { type DataTableColumn } from "./data-table-features";
import {
  useDataTableColumnHeader,
  type DataTableColumnHeaderHostProps,
  type DataTableColumnHeaderProps,
} from "./useDataTable";

const DataTableColumnHeaderHost = cc<DataTableColumnHeaderHostProps>(
  ({ column, title, class: className }) => {
    const header = useDataTableColumnHeader(column);
    if (!header.canSort) {
      return (
        <div class={cn("text-sm font-medium", className)} data-slot="data-table-column-title">
          {title}
        </div>
      );
    }

    return (
      <div class={cn("flex items-center gap-2", className)}>
        <DropdownMenu>
          <DropdownMenuTrigger
            class={cn(
              buttonVariants({ variant: "ghost", size: "sm" }),
              "-ms-3 h-8 gap-1",
            )}
          >
            <span>{title}</span>
            {header.sorted.value === "desc" ? (
              <Icon icon={ArrowDown} class="size-4" />
            ) : header.sorted.value === "asc" ? (
              <Icon icon={ArrowUp} class="size-4" />
            ) : (
              <Icon icon={ChevronsUpDown} class="size-4" />
            )}
          </DropdownMenuTrigger>
          <DropdownMenuContent align="start">
            <DropdownMenuItem onclick={header.sortAscending}>
              <Icon icon={ArrowUp} class="size-4" />
              Asc
            </DropdownMenuItem>
            <DropdownMenuItem onclick={header.sortDescending}>
              <Icon icon={ArrowDown} class="size-4" />
              Desc
            </DropdownMenuItem>
            {header.canHide ? (
              <>
                <DropdownMenuSeparator />
                <DropdownMenuItem onclick={header.hide}>
                  <Icon icon={EyeOff} class="size-4" />
                  Hide
                </DropdownMenuItem>
              </>
            ) : null}
          </DropdownMenuContent>
        </DropdownMenu>
      </div>
    );
  },
);

export function DataTableColumnHeader<TData extends RowData, TValue>(
  props: DataTableColumnHeaderProps<TData, TValue>,
): SinwanNode {
  return (
    <DataTableColumnHeaderHost
      column={props.column as DataTableColumn}
      title={props.title}
      class={props.class}
    />
  );
}

import { onUnmounted, type SinwanNode } from "sinwan/component";
import { signal, type Signal } from "sinwan/reactivity";
import { FlexRender, type FlexRenderProps } from "@tanstack/table-core/flex-render";
import type { RowData } from "@tanstack/table-core";

import {
  type DataTableFeatures,
  type DataTableInstance,
} from "./data-table-features";

/**
 * TanStack `FlexRender` returns `unknown`. Narrow it to a Sinwan child without
 * hiding incompatible values behind a double assertion.
 */
export function toTableNode(value: unknown): SinwanNode {
  if (
    value == null ||
    typeof value === "string" ||
    typeof value === "number" ||
    typeof value === "boolean"
  ) {
    return value;
  }
  if (typeof value === "function" || typeof value === "object") {
    return value as SinwanNode;
  }
  return String(value);
}

export function DataTableFlexRender<TData extends RowData>(
  props: FlexRenderProps<DataTableFeatures, TData>,
): SinwanNode {
  return toTableNode(FlexRender(props));
}

export function useTableRevision(
  table: DataTableInstance,
): Signal<number> {
  const revision = signal(0);
  const subscription = table.store.subscribe(() => {
    revision.value += 1;
  });
  onUnmounted(() => {
    subscription.unsubscribe();
  });
  return revision;
}

import { cc, type SinwanNode } from "sinwan/component";
import {
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
} from "lucide";
import type { RowData } from "@tanstack/table-core";

import { Icon } from "@/lib/icons";
import { cn } from "@/lib/utils";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import { NativeSelect, NativeSelectOption } from "@/components/ui/native-select";
import { type DataTableInstance } from "./data-table-features";
import {
  DEFAULT_DATA_TABLE_PAGE_SIZES,
  useDataTablePagination,
  type DataTablePaginationHostProps,
  type DataTablePaginationProps,
} from "./useDataTable";

const DataTablePaginationHost = cc<DataTablePaginationHostProps>(
  ({ table, pageSizes, class: className }) => {
    const pagination = useDataTablePagination(table);
    const { revision } = pagination;

    return (
      <div
        data-slot="data-table-pagination"
        class={cn(
          "flex flex-col gap-3 py-4 sm:flex-row sm:items-center sm:justify-between",
          className,
        )}
      >
        <div
          class="flex-1 text-sm text-muted-foreground"
          data-slot="data-table-selected-count"
        >
          {pagination.selectedText.value}
        </div>
        {(revision.value, (
            <div class="flex flex-wrap items-center gap-4 lg:gap-6">
              <div class="flex items-center gap-2">
                <Label class="text-sm font-medium whitespace-nowrap">
                  Rows per page
                </Label>
                <NativeSelect
                  data-slot="data-table-page-size"
                  aria-label="Rows per page"
                  size="sm"
                  value={pagination.pageSize.value}
                  onchange={pagination.onPageSizeChange}
                >
                  {pageSizes.map((size) => (
                    <NativeSelectOption value={String(size)}>
                      {size}
                    </NativeSelectOption>
                  ))}
                </NativeSelect>
              </div>
              <div
                class="text-sm font-medium whitespace-nowrap"
                data-slot="data-table-page-status"
              >
                {pagination.pageStatus.value}
              </div>
              <div class="flex items-center gap-1">
                <Button
                  variant="outline"
                  size="icon-sm"
                  data-slot="data-table-first-page"
                  aria-label="Go to first page"
                  disabled={!pagination.canPreviousPage.value}
                  onclick={pagination.firstPage}
                >
                  <Icon icon={ChevronsLeft} class="rtl:rotate-180" />
                </Button>
                <Button
                  variant="outline"
                  size="icon-sm"
                  data-slot="data-table-previous-page"
                  aria-label="Go to previous page"
                  disabled={!pagination.canPreviousPage.value}
                  onclick={pagination.previousPage}
                >
                  <Icon icon={ChevronLeft} class="rtl:rotate-180" />
                </Button>
                <Button
                  variant="outline"
                  size="icon-sm"
                  data-slot="data-table-next-page"
                  aria-label="Go to next page"
                  disabled={!pagination.canNextPage.value}
                  onclick={pagination.nextPage}
                >
                  <Icon icon={ChevronRight} class="rtl:rotate-180" />
                </Button>
                <Button
                  variant="outline"
                  size="icon-sm"
                  data-slot="data-table-last-page"
                  aria-label="Go to last page"
                  disabled={!pagination.canNextPage.value}
                  onclick={pagination.lastPage}
                >
                  <Icon icon={ChevronsRight} class="rtl:rotate-180" />
                </Button>
              </div>
            </div>
          ))}
      </div>
    );
  },
);

export function DataTablePagination<TData extends RowData>(
  props: DataTablePaginationProps<TData>,
): SinwanNode {
  return (
    <DataTablePaginationHost
      table={props.table as DataTableInstance}
      pageSizes={props.pageSizes ?? DEFAULT_DATA_TABLE_PAGE_SIZES}
      class={props.class}
    />
  );
}

import { cc, type SinwanNode } from "sinwan/component";
import type { RowData } from "@tanstack/table-core";

import { Checkbox } from "@/components/ui/checkbox";
import {
  type DataTableInstance,
  type DataTableRow,
} from "./data-table-features";
import { useDataTableSelectAll, useDataTableSelectRow } from "./useDataTable";

const DataTableSelectAllHost = cc<{ table: DataTableInstance }>(({ table }) => {
  const selectAll = useDataTableSelectAll(table);
  return (
    <Checkbox
      aria-label="Select all"
      checked={selectAll.checked.value}
      indeterminate={selectAll.indeterminate.value}
      onCheckedChange={selectAll.toggle}
    />
  );
});

const DataTableSelectRowHost = cc<{ row: DataTableRow }>(({ row }) => {
  const selectRow = useDataTableSelectRow(row);
  return (
    <Checkbox
      aria-label="Select row"
      checked={selectRow.checked.value}
      onCheckedChange={selectRow.toggle}
    />
  );
});

export function DataTableSelectAll<TData extends RowData>(props: {
  table: DataTableInstance<TData>;
}): SinwanNode {
  return <DataTableSelectAllHost table={props.table as DataTableInstance} />;
}

export function DataTableSelectRow<TData extends RowData>(props: {
  row: DataTableRow<TData>;
}): SinwanNode {
  return <DataTableSelectRowHost row={props.row as DataTableRow} />;
}

